import {replayWagers,patchBoard} from './craps-wager-queue.mjs';
import {rollHeadline,winningCell} from './craps-result.mjs';
import {Craps,LABELS} from './craps.mjs';
import {BET_GROUPS,cellsForGroup} from './craps-single-layout.mjs';
import {extraError} from './craps-extra.mjs';
import {Craps3D} from './craps3d.mjs';
import {BET_CELLS,FELT_CAPTIONS,CRAPS_TIMING,SEAT_COLORS,wagerTotal} from './craps-layout.mjs';
const escapeName=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const CRAPS_RULES=`<p>两颗独立公平六面骰，仅使用虚拟筹码。赔率表示净赢，本金按下列规则返还。桌布仅显示一套下注区。格内列出玩家姓名与金额；上方可切换其他下注类别。</p><ol><li>下注不限时，掷骰者随时点击投掷；点击后立即锁定下注并进入掷骰视角。骰子停稳后展示 3 秒，再回到俯视桌布结算。只有目标已建立后掷出 7（七出）才换掷骰者。</li><li>Pass Line：开局 7 / 11 赢，2 / 3 / 12 输；其余建立目标，再中目标赢，先出 7 输。Don’t Pass 相反，但开局 12 退回。两者均赔 1:1。</li><li>COME / Don’t Come：目标建立后可下。第一掷按开局规则结算；掷出 4 / 5 / 6 / 8 / 9 / 10 后，筹码移到该数字，成为独立合约。之后 COME 等该数字先于 7 出现，Don’t Come 等 7 先出现，均赔 1:1；首掷 Don’t Come 的 12 退回。已移点合约在开局掷也生效；COME 合约锁定，Don’t Come 可在明细中撤回。</li><li>FIELD：每掷结算，2 / 12 赔 2:1，3 / 4 / 9 / 10 / 11 赔 1:1，其余输。</li><li>PLACE：只在目标 ON 时生效；数字先于 7 出现则赢，7 出现则输。4 / 10 赔 9:5，5 / 9 赔 7:5，6 / 8 赔 7:6。快捷筹码按下注区单位自动取整；自定义金额按输入的正整数原额下注，每笔输赢四舍五入为整数。赢后本金留桌。</li><li>HARD 4 / 10 赔 7:1，HARD 6 / 8 赔 9:1。对应对子赢，7 或同总点数非对子输，其他继续等待。开局也生效，赢后本金留桌。</li><li>BIG 6 / 8：数字先于 7 出现赢 1:1，7 输；每掷生效，赢后本金留桌。相较 Place，同数字的 Big 赔率更低。</li><li>单掷注：ANY 7 赔 4:1；ANY CRAPS（2 / 3 / 12）赔 7:1；指定 2 / 12 赔 30:1；指定 3 / 11 赔 15:1。下一掷未命中即输。</li><li>撤回模式仅撤可撤的筹码，已建立目标的 Pass 和已移点的 COME 不能撤回。Odds：对应底注建立点数后追加，最多为底注 5 倍；顺买真赔率为 4/10 赔 2:1、5/9 赔 3:2、6/8 赔 6:5，反向赔率取倒数。COME Odds 在开局掷 OFF，若底注结算则退回；Don’t Come Odds 始终生效。</li><li>Buy 按真赔率，在目标 ON 时生效，赢时收本金 5% 佣金；Lay 每掷生效，7 先出赢，收利润 5% 佣金。佣金向上取整至 1 筹码，输不收佣金；赢后本金留桌。</li><li>Horn 等分为 2/3/11/12 四份；Horn High 五份中指定数字占两份。World / Whirl 等分为四个 Horn 数字和 Any 7，出 7 净变化为零。C&E 各半分给 Any Craps 和 11。组合注按各部分实际输赢合计，下一掷结算。</li><li>Hop 覆盖 21 种无序骰面组合，对子赔 30:1，非对子赔 15:1，下一掷不匹配则输。各赌场专有的连胜奖励注不包含在本桌规则内。</li></ol>`;
export class CrapsUI{
 constructor(host,{bank,onBank,onExit,onRules,beep,toast,reduced,network=null}){
  Object.assign(this,{host,onBank,onExit,onRules,beep,toast,network});this.engine=new Craps(bank);this.wagerQueue=[];this.wagerFlight=[];this.chip=10;this.selected='pass';this.betGroup='main';this.removing=false;this.alive=true;this.message='选择筹码，点击下注区 · 格内显示同桌玩家金额';
  document.body.classList.add('in-game','craps-game');
  host.innerHTML=`<section class="craps-room"><div class="craps-scene"></div><header class="craps-heading"><div><small>THE EMBER TAVERN</small><h1>花旗骰 <span>CRAPS</span></h1></div><button data-cfull>⛶ 全屏</button><button data-crules>玩法</button><button data-cexit>离开牌桌 ↗</button></header><div class="craps-clock" role="status"></div><div class="craps-status"></div><div class="craps-readout" aria-live="polite"></div><div class="craps-board"></div><aside class="craps-ledger"></aside><div class="craps-dock"></div></section>`;
  this.q=s=>host.querySelector(s);this.q('[data-cexit]').onclick=()=>this.exit();this.q('[data-crules]').onclick=onRules;
  this.q('[data-cfull]').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('可使用浏览器全屏功能')}};
  try{this.scene=new Craps3D(this.q('.craps-scene'),{reduced,onImpact:()=>this.beep('dice')})}catch(e){console.warn('Craps WebGL unavailable',e);this.q('.craps-scene').innerHTML='<p class="craps-fallback">3D 暂不可用，点数面板仍会显示本掷结果。</p>'}
  this.render();this.timer=setInterval(()=>this.updateClock(),200);
 }
 get phase(){return this.network?.phase??this.localPhase??(this.engine.rolling?'rolling':'bets')}
 updateClock(){const phase=this.phase,node=this.q('.craps-clock');if(!node)return;const now=Date.now()+(this.network?.clockOffset??0),seconds=Math.max(0,Math.ceil(((this.network?.deadline??this.betDeadline)-now)/1000));
  node.innerHTML=phase==='bets'?'<b>自由下注</b><span>掷骰者可随时开始</span>':phase==='rolling'?'<b>投掷中</b><span>下注已锁定</span>':phase==='landed'?'<b>点数确认</b><span>停留 3 秒后结算</span>':phase==='result'?'<b>本掷结算</b>':'<b>下注结束</b><span>'+(!this.network||this.network.canRoll?'由你决定何时掷骰':'等待掷骰者投掷')+'</span>';
  if(this.renderedPhase!==phase)this.render();
 }
 sync(){this.onBank(this.engine.bank)}
 render(){
  const readout=this.q('.craps-readout');const ledgerOpen=this.q('.craps-ledger details')?.open,ledgerScroll=this.q('.craps-wager-list')?.scrollTop??0;
  const g=this.engine,phase=this.phase,locked=phase!=='bets',immersive=['ready','rolling','landed'].includes(phase);this.renderedPhase=phase;
  this.q('.craps-room').dataset.phase=phase;this.q('.craps-room').classList.toggle('is-immersive',immersive);this.q('.craps-room').classList.toggle('is-rolling',phase==='rolling');
  this.scene?.setPhase(phase);this.q('.craps-status').innerHTML=`<span class="point-puck ${g.point?'on':''}">${g.point||'OFF'}</span><strong>${g.point?'目标 '+g.point:'COME OUT'}</strong><span>桌上筹码 <b>${g.escrow}</b></span>`;
  const last=g.history[0],landed=this.network?.roll?.dice??this.pendingDice;
  this.q('.craps-readout').innerHTML=phase==='landed'&&landed?`<div class="dice-result"><span>${landed[0]}</span><i>+</i><span>${landed[1]}</span><b>= ${landed[0]+landed[1]}</b></div><p class="craps-event">${rollHeadline(landed,g.point)}</p>`:`<p>${phase==='rolling'?'跟随骰子 · 等待停稳':escapeName(this.message)}</p>${last&&!immersive?`<strong class="craps-event">${rollHeadline(last.dice,last.oldPoint)}</strong><small>上一掷 ${last.dice.join(' + ')} = ${last.total} · 本掷净变化 <b>${last.net>0?'+':''}${last.net}</b></small>`:''}`;
  const others=this.network?.others??[{name:'你',bank:g.bank,escrow:g.escrow,bets:g.bets,travel:g.travel,last}];
  if(this.network){const totals=others.map(p=>Object.values(p.bets).reduce((a,b)=>a+b,0));if(this.betTotals&&totals.some((v,i)=>v>this.betTotals[i]))this.beep?.('chips');this.betTotals=totals}
  const bet=c=>{const disabled=locked||(!this.removing&&!!extraError(g,c.key,g.amount(c.key,this.chip,this.customAmount)))||(!this.removing&&g.point&&['pass','dont'].includes(c.key))||(!this.removing&&!g.point&&['come','dcome'].includes(c.key))||(this.removing&&g.point&&c.key==='pass');
   const wagers=others.map((p,i)=>{const n=wagerTotal(p,c.key);return n?`<b style="--chip:${SEAT_COLORS[i%8]}" title="${escapeName(p.name)}：${n}"><span>${escapeName(p.name)}</span><em>${n}</em></b>`:''}).join('');
   return `<button class="craps-bet ${c.kind} ${!immersive&&winningCell(c.key,last)?'roll-hit':''} ${this.selected===c.key?'selected':''} ${wagers?'has-bet':''} ${g.point===Number(c.key.slice(1))&&c.kind==='point'?'target-number':''}" style="--span:${c.span??1}" data-bet="${c.key}" ${disabled?'disabled':''} aria-label="${LABELS[c.key]}，${c.detail}，${this.removing?'撤回':'增加 '+g.amount(c.key,this.chip,this.customAmount)}，你的下注 ${wagerTotal({bets:g.bets,travel:g.travel},c.key)}"><strong>${c.label}</strong><small>${c.detail}</small>${c.kind==='hard'?`<span class="tiny-dice">${['','⚀','⚁','⚂','⚃','⚄','⚅'][Number(c.key.slice(1))/2]} ${['','⚀','⚁','⚂','⚃','⚄','⚅'][Number(c.key.slice(1))/2]}</span>`:''}<span class="felt-wagers">${wagers||'<i>暂无下注</i>'}</span></button>`;
  };
  const group=this.betGroup??'main';
  patchBoard(this.q('.craps-board'),`<nav class="craps-bet-groups" aria-label="下注类别">${BET_GROUPS.map(([key,label])=>{const total=cellsForGroup(key).reduce((sum,c)=>sum+(g.bets[c.key]??0),0);return `<button data-bet-group="${key}" class="${key===group?'selected':''}" aria-pressed="${key===group}">${label}${total?'<b>'+total+'</b>':''}</button>`}).join('')}</nav><div class="craps-wood-frame"><div class="craps-felt single-felt">${cellsForGroup(group).map(bet).join('')}</div></div>`);
  if(immersive)this.q('.craps-room').append?.(readout);else this.q('.craps-board').prepend?.(readout);
  this.host.querySelectorAll('[data-bet-group]').forEach(b=>b.onclick=()=>{this.betGroup=b.dataset.betGroup;this.render()});
  this.q('.craps-ledger').innerHTML=`<div class="craps-seat-legend">${others.map((p,i)=>`<span><i style="background:${SEAT_COLORS[i%8]}"></i>${escapeName(p.name)}<b class="player-chip-total">◉ ${Number((p.bank??0)+(p.escrow??0)).toLocaleString()}</b>${p.last&&!immersive?'<b class="round-net '+(p.last.net>=0?'positive':'negative')+'">本掷 '+(p.last.net>0?'+':'')+p.last.net+'</b>':''}</span>`).join('')}</div><div class="craps-selected"><b>${LABELS[this.selected]??'Pass Line'}</b><span>${this.removing?'撤回可撤注':'点击增加 '+g.amount(this.selected??'pass',this.chip,this.customAmount)}</span>${others.map((p,i)=>`<span style="color:${SEAT_COLORS[i%8]}">${escapeName(p.name)} ${wagerTotal(p,this.selected??'pass')}</span>`).join('')}</div><details><summary>下注与本掷输赢明细</summary><div class="craps-wager-list">${others.map((p,i)=>`<section><b style="color:${SEAT_COLORS[i%8]}">${escapeName(p.name)}</b>${p.last&&!immersive?p.last.events.map(e=>'<span class="settled-event '+(e.profit>0?'positive':e.profit<0?'negative':'')+'">'+(LABELS[e.key]??e.key)+' <b>'+(e.profit>0?'+':'')+e.profit+(e.travel?' → '+e.travel:'')+'</b></span>').join(''):''}${Object.entries(p.bets).filter(([,v])=>v).map(([k,v])=>`<span>${LABELS[k]} <b>${v}</b></span>`).join('')}${Object.entries(p.travel??{}).filter(([,v])=>v).map(([k,v])=>`<span>${k[0]==='c'?'COME':'Don’t Come'} → ${k.slice(1)} <b>${v}</b></span>`).join('')}${![...Object.values(p.bets),...Object.values(p.travel??{})].some(Boolean)?'<small>暂无下注</small>':''}</section>`).join('')}${Object.entries(g.travel??{}).filter(([k,v])=>v&&k[0]==='d').map(([k,v])=>`<button data-travel="${k}" ${locked?'disabled':''}>撤回你的 Don’t Come → ${k.slice(1)} · ${v}</button>`).join('')}</div></details>`;
  const dockHtml=`<label class="custom-wager">下注金额<input data-custom-wager type="number" min="1" step="1" inputmode="numeric" aria-label="自定义下注金额" ${locked?'disabled':''}></label><div class="craps-chip-picker" aria-label="选择筹码">${[5,10,25,100].map((n,i)=>`<button data-chip="${n}" style="--chip:${SEAT_COLORS[i]}" class="${this.chip===n?'selected':''}" aria-pressed="${this.chip===n}" ${locked?'disabled':''}>${n}</button>`).join('')}</div><button data-remove aria-pressed="${this.removing}" class="${this.removing?'selected':''}" ${locked?'disabled':''}>${this.removing?'返回下注':'撤回模式'}</button><button data-clear ${locked?'disabled':''}>清除可撤注</button><button class="craps-roll" data-roll ${phase!=='bets'||this.network&&!this.network.canRoll?'disabled':''}>${phase==='rolling'?'骰子翻滚中…':phase==='landed'?'点数已确认':phase==='bets'&&(!this.network||this.network.canRoll)?'由你掷骰 ↗':'等待掷骰'}</button>`;
  this.host.querySelectorAll('[data-bet]').forEach(b=>b.onclick=()=>{this.selected=b.dataset.bet;this.act(this.removing?'remove':'bet',b.dataset.bet)});
  this.host.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>this.act('removeTravel',b.dataset.travel));
  const dock=this.q('.craps-dock'),focused=this.q('[data-custom-wager]')===document.activeElement;
  if(dock._wagerHtml!==dockHtml){dock.innerHTML=dockHtml;dock._wagerHtml=dockHtml;if(focused)this.q('[data-custom-wager]').focus({preventScroll:true})}
  const input=this.q('[data-custom-wager]');input.value=this.customDraft??String(this.chip);input.oninput=e=>{this.customDraft=e.target.value;this.chip=Number(e.target.value);this.customAmount=true;this.removing=false;this.render()};
  this.host.querySelectorAll('[data-chip]').forEach(b=>b.onclick=()=>{this.chip=+b.dataset.chip;this.customDraft=String(this.chip);this.customAmount=false;this.removing=false;this.render()});
  this.q('[data-remove]').onclick=()=>{this.removing=!this.removing;this.render()};this.q('[data-clear]').onclick=()=>this.act('clear');this.q('[data-roll]').onclick=()=>this.roll();
  if(ledgerOpen&&this.q('.craps-ledger details')){this.q('.craps-ledger details').open=true;this.q('.craps-wager-list').scrollTop=ledgerScroll}
  this.scene?.setWagers(others);this.updateClock();
 }
 act(action,key){if(this.phase!=='bets')return;if(action==='bet'&&(!Number.isSafeInteger(this.chip)||this.chip<1)){this.toast('请输入大于0的整数下注金额');return}if(this.network){try{const a={action,key,amount:this.chip,exact:!!this.customAmount};this.engine=replayWagers(this.engine,[a]);this.wagerQueue.push(a);this.updateDraft();this.render();clearTimeout(this.wagerTimer);this.wagerTimer=setTimeout(()=>this.flushWagers(),60)}catch(e){this.toast(e.message)}return}try{const g=this.engine;if(action==='bet')g.add(key,this.chip,!!this.customAmount);else if(action==='remove')g.remove(key);else if(action==='removeTravel')g.removeTravel(key);else g.clear();this.sync();this.beep('chips');this.render()}catch(e){this.toast(e.message)}}
 ackWagers(){this.wagerFlight=[]}
 updateDraft(){if(this.network?.others&&this.network.you>=0){this.network.others=this.network.others.map((p,i)=>i===this.network.you?{...p,bets:this.engine.bets,travel:this.engine.travel,bank:this.engine.bank}:p)}const wallet=document.querySelector('#wallet');if(wallet)wallet.textContent=this.engine.bank.toLocaleString()}
 replayPending(){if(this.phase!=='bets'){this.wagerQueue=[];return}try{this.engine=replayWagers(this.authoritative,[...this.wagerFlight,...this.wagerQueue]);this.updateDraft()}catch{this.wagerQueue=[];this.toast('部分下注未成功，请核对桌上金额')}}
 async flushWagers(){if(!this.alive||!this.wagerQueue.length||this.wagerFlight.length)return;if(!this.network.canSend()){this.wagerTimer=setTimeout(()=>this.flushWagers(),60);return}this.wagerFlight=this.wagerQueue.splice(0,32);try{await this.network.send({action:'betBatch',bets:this.wagerFlight})}catch{this.wagerFlight=[];this.wagerQueue=[];this.replayPending();if(this.alive)this.render()}finally{if(this.alive&&this.wagerQueue.length)this.wagerTimer=setTimeout(()=>this.flushWagers(),0)}}
 async roll(){
  if(this.wagerQueue.length||this.wagerFlight.length){this.toast('下注正在确认，稍后即可掷骰');this.flushWagers();return}
  if(this.network){await this.network.send({action:'roll'}).catch(()=>{});return}if(this.phase!=='bets')return;
  const g=this.engine;let dice;try{dice=g.begin()}catch{this.toast('无法启动安全随机数，请使用 HTTPS');return}
  this.pendingDice=dice;this.localPhase='rolling';this.render();
  try{if(this.scene)await this.scene.throw(dice);else await this.wait(CRAPS_TIMING.throw)}catch(e){console.warn(e)}if(!this.alive)return;
  this.localPhase='landed';this.render();await this.wait(CRAPS_TIMING.hold);if(!this.alive)return;
  const r=g.settle(dice);this.localPhase=null;this.message=`${dice.join(' + ')} = ${r.total} · ${r.oldPoint&&!r.point?(r.total===7?'七出 · 开启下一轮':'命中目标 · 开启下一轮'):!r.oldPoint&&r.point?'目标建立':r.point?'继续追逐目标':'等待下一次开局'}`;this.sync();if(r.net>0)this.beep('win');this.render();
 }
 wait(ms){return new Promise(resolve=>{this.waitResolve=resolve;this.waitTimer=setTimeout(()=>{this.waitResolve=null;resolve()},ms)})}
 exit(){if(this.network){this.network.exit();return}if(this.engine.rolling){this.toast('请等骰子停稳并结算后离桌');return}const locked=(this.engine.point?this.engine.bets.pass:0)+Object.entries(this.engine.travel??{}).filter(([k])=>k[0]==='c').reduce((s,[,v])=>s+v,0);if(locked&&!confirm(`还有 ${locked} 筹码的合约已锁定。离桌将放弃这些筹码，其余可撤注退回。确定离开？`))return;this.engine.clear();this.sync();this.onExit()}
 destroy(){this.alive=false;clearInterval(this.timer);clearTimeout(this.wagerTimer);clearTimeout(this.waitTimer);this.waitResolve?.();this.scene?.destroy();document.body.classList.remove('craps-game')}
}
